 p=v/f'src/main/resources/assets/building_wand/lang/{lang}.json';d=json.loads(p.read_text(encoding='utf-8'));d.update(zip(keys,values));p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
