p=v/'src/main/java/cn/quit5700/buildingwand/server/StructurePlacement.java';s=p.read_text(encoding='utf-8');s=s.replace('  var old=new LinkedHashMap<BlockPos,BlockState>();','''  if(desired.size()==1){var e=desired.entrySet().iterator().next();if(!multiple(e.getValue().getBlock())&&!(e.getValue().getBlock() instanceof ChestBlock)){
   boolean ok=w.getBlockState(e.getKey()).equals(e.getValue())||w.setBlock(e.getKey(),e.getValue(),Block.UPDATE_ALL);
   if(ok){connect(w,e.getKey());for(var d:Direction.values())connect(w,e.getKey().relative(d));}return ok;
  }}
  var old=new LinkedHashMap<BlockPos,BlockState>();''');p.write_text(s,encoding='utf-8')
