p=v/'src/main/java/cn/quit5700/buildingwand/server/BuildTaskState.java';s=p.read_text(encoding='utf-8');s=s.replace('blocked|=!w.isInWorldBounds(at)', 'blocked|=(e.getValue().isAir()&&w.getBlockEntity(at)!=null)||!w.isInWorldBounds(at)');p.write_text(s,encoding='utf-8')
